                        actVymahat: {
                            name: "actVymahat",
                            caption: "Vymáhat",
                            tooltip: "Provede generaci vymáhání na vybraných případech",
                            run: () => {
                                var sel = that.gridSeznamPripadu?.ggrid("getSelection");
                                if (sel.length != 0) {
                                    var form = that.formularVymahani();
                                    // Watch for the wizParams form being appended to the DOM
                                    const observer = new MutationObserver((mutations) => {
                                        mutations.forEach((mutation) => {
                                            mutation.addedNodes.forEach((node) => {
                                                // Check if the appended node is the wizParams form
                                                if ($(node).is('[data-form="wizParams"]') || $(node).find('[data-form="wizParams"]').length > 0) {
                                                    // Call the initialization function when the form is ready
                                                    that.inicialniHodnotyProFormularVymahani();
                                                    // Disconnect observer since we only need this once
                                                    observer.disconnect();
                                                }
                                            });
                                        });
                                    });
                                    // Start observing the document body for changes
                                    observer.observe(document.body, { childList: true, subtree: true });
                                    const checkFunction = that.isl.VymahaniDDP.kontrolaVymahani.bind(that.isl.VymahaniDDP);
                                    that.hromadnaOperaceVymahaniAsync(sel, "Generace vymáhání", WebClient.Common.GridFormats.HrmAkceSimple(), "ixp", form, "Výsledek změny", checkFunction, "Opravdu chcete provést vymáhání případu?", ""); //, [{ favorite: true, action: that.actions.actHistorieVym }]
                                }
                            }
                        },
