                            name: "actTiskPredani",
                            caption: "Tisk",
                            tooltip: "Tisk předávacího protokolu",
                            enabled: false,
                            run: (ev, ctx) => {
                                var cnt = $.content(ev.target);
                                that.tiskPredani(cnt);
                            }
