                /** Vytvoří grid/seznam případů */
                createGrid() {
                    const that = this;
                    var actionList = new GActionList({
                        actPredat: {
                            enabled: that.params.ddp_rad_dokpre == 1,
                            caption: "Předat",
                            icon: "gi-predat",
                            run: () => {
                                const checkFunction = that.isl.Redistribuce.kontrolaPredani.bind(that.isl.Redistribuce);
                                that.wizzardRedist(checkFunction, 0);
                            }
                        },
                        actPridelit: {
                            enabled: that.params.ddp_rad_dokprd == 1,
                            caption: "Přidělit",
                            icon: "gi-pridelit",
                            run: () => {
                                const checkFunction = that.isl.Redistribuce.kontrolaPredani.bind(that.isl.Redistribuce);
                                that.wizzardRedist(checkFunction, 10);
                            }
                        },
                        actPrevzit: {
                            enabled: that.params.ddp_rad_dokpri == 1,
                            caption: "Převzít",
                            icon: "gi-prevzit",
                            run: () => {
                                that.prevzit();
                            }
                        }
                    });
                    //?priz_spr == 1
                    var columnList = "typ_entity_ico,vlastnictvi,el_prilohy_pocet,el_obraz_typ, s_fyz, s_ele, ixp, typ_phl, ktg_upo, up_stav_txt, zp, dat_vyst, dat_evid, ac, popis, c_celk,c,kurz,ExterniSubjekt.dat_nar,ExterniSubjekt.esu_txt,ixs_fun_akt,ixp_den";
                    if (that.PrizSpr == 1) {
                        // Insert pic_stavpredanispr after el_obraz_typ
                        columnList = columnList.replace("el_obraz_typ,", "el_obraz_typ, pic_stavpredanispr,");
                        columnList += ",stav_pred, cis_spr";
                    }
                    that.gridSeznamPripadu = $.newDiv("GPripadySeznamGridDiv")
                        .css("height", "100%")
                        .appendTo(this.element)
                        .gautofit()
                        .ggrid({
                        //.ggrid({
                        name: "GPripadySeznamGrid",
                        data: that.view,
                        columnMode: "full",
                        //columnMode: "fit",
                        renderMode: "paged-async", // auto, all-at-once, paged-sync, paged-async
                        multi: true,
                        navigationMode: "row",
                        defaultAction: this.actions["actGPripadySeznamGridVychoziAkce"],
                        scrollHelperTemplate: "{ExterniSubjekt.esu_txt}",
                        searchColumns: ["ixp", "vs", "ac", "ExterniSubjekt.esu_txt"],
                        //searchColumns: ["*"], //
                        columns: WebClient.Common.GridFormats.Pripady(),
                        rowNumbers: false,
                        defaultProfile: {
                            name: "Výchozí pohled", _locked: true, _default: true,
                            //columnList: "ixp, vs, ExterniSubjekt.dat_nar, ExterniSubjekt.esu_txt, typ_phl, c_celk, aktivita", //, dat_evid,",// dat_zmena, ",
                            columnList: columnList,
                            condFormats: [
                                //{ description: "Neaktivní", formula: "IF(NOT(ISBLANK(@up_stav)) and ((@up_stav == 10) or (@up_stav == 38)), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.purple },
                                { description: "Neaktivní", formula: "IF(NOT(ISBLANK(@aktivita)) and (@aktivita != 100), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.purple },
                                //{ description: "Stornovaný", formula: "IF(NOT(ISBLANK(@s_sto)) and (@s_sto == 0), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.red },
                                //{ description: "Stornovací", formula: "IF(NOT(ISBLANK(@s_sto)) and (@s_sto == 20), true, false, false)", text: Gordic.Components.Grid.CondFormats.CondFormatText.orange }
                            ]
                        },
                        contextMenu: function (cellContext) {
                            return actionList.createBar([
                                "actPredat",
                                "actPridelit",
                                "actPrevzit",
                            ]);
                        },
                        cellActivate: (ev, ctx) => {
                            if (!this.closed) {
                                if (ctx != null &&
                                    ctx.cellInfo != null &&
                                    ctx.cellInfo.data != null) {
                                    this.previewController.enable(true);
                                    this.previewController.show(ctx.cellInfo.data);
                                }
                                else {
                                    this.previewController.enable(false);
                                }
                            }
                        },
                    }).ggridrowscalc();
                    //.ggrideko({
                    //    // součtový řádek
                    //    summaryRowAllowed: true,
                    //    // dlouhý seznam
                    //    longListAllowed: false,
                    //    //longListModel: "Global.Pok.AppSettings",
                    //});
                }
                /** Funkce pro vytvoření eko filtr-panelu */
                createFilter() {
                    const that = this;
                    //! Vytvoření standardních parametrů filterpanelu pro EKO moduly
                    let filterParams = Gordic.Eko.Filters.getFilterParams([
                        that.createFilterFormSettings(),
                        that.createFilterFormVlastnosti(),
                        that.createFilterFormCastky(),
                        that.createFilterFormExterniSubjekt(),
                        that.createFilterDopUdajeForm(),
                        that.createFilterPredpPlatVratky(),
                        //that.createFilterPohledavkyNks(),
                        that.createFilterSpravci(),
                        that.createFilterVymahani(),
                        that.createFilterOprPolSpis(),
                        that.createFilterPenalizace(),
                        that.createFilterTiskyZverejneni(),
                        that.createFilterPohybyPoznamky(),
                        that.createFilterRozhodKontrLhuty(),
                    ], ["ixp", "typ_phl"], // TODO: doplnit nějaké oblíbené filtry
                    "ddp_ptm_opis", //téme tisku
                    "ixs_fun_akt", //sloupec z DTO pro filtr "*vlastní" nebo null, pokud nemá být
                    function (event, obj) {
                        that.filters = obj.filter;
                    }, 
                    //undefined, //TODO: možná předělat zpět na použití that.ziskejData(obj.filter);
                    //function (event, obj) {
                    //    that.filterData = obj.filter;
                    //    //metoda pro načtení seznamu
                    //    that.ziskejData(obj.filter);
                    //},
                    undefined, //pevný filtr
                    true, // zobrazit navigátor v detailu filtru? - ROZHODNĚ TRUE v tomto případě navigátor bude sloužit obdobně jako záložky v TK
                    // 17.01.2024 - TFeik - Doplnění parentContentu pro odstranění zombie contentu.
                    that);
                    filterParams.strictStopAutoLoad = true; // Zakáže automatické vyhledávání po vytvoření filtru
                    that.filter = $.newDiv().appendTo(this.element)
                        .gfilterpanel(filterParams);
                    that.filter.on("click", (ev) => {
                        // získám formulář filter panelu s daným help contextem
                        var contextFilterForms = $(document.body).find("[data-help-context='content:Detgfilterpanel&filterpanelDetailFiltru']");
                        if (contextFilterForms.length > 0) {
                            if (contextFilterForms.length == 2)
                                that.filtrPanelForm = $(contextFilterForms[1]);
                            else
                                that.filtrPanelForm = $(contextFilterForms[0]);
                            that.vsInterval();
                            that.strictniRezimFilterPanel();
                        }
                    });
                    that.view = new Gordic.Isl.View(that.isl.Pripad.list(rq => rq), {
                        filterPanel: that.filter,
                        key: ["ixp"],
                        startEmpty: true
                    });
                }
