                createFilterFormSettings() {
                    return new Gordic.Forms.Form({ name: "settingsForm", tabLabel: "Nastavení", layoutDescriptor: "L2M1S1, L-12-12-0, M-12-12-0, S-12-12-0" })
                        .addSection()
                        .addRow()
                        .addField("gcheck", "w-6", {
                        name: "case_sensitive",
                        label: "Rozlišovat velikost písmen",
                    })
                        .addField("gcheck", "w-6", {
                        name: "bez_diakritiky",
                        label: "Ignorovat diakritiku"
                    });
                }
                /** Vytvoří FORMulář podle záložky HLAVNÍ v TK */
