                /**Metoda pro vytvoření menu na contentu */
                createMenu() {
                    const that = this;
                    let menu = [
                        {
                            caption: "Detail",
                            tooltip: "Detail případu",
                            icon: "gi-detail",
                            action: that.actions["actGPripadySeznamGridVychoziAkce"],
                            favorite: false,
                        },
                        {
                            caption: "Podání",
                            tooltip: "Podání nového případu",
                            icon: "gi-plus",
                            action: that.actions["actGPripadySeznamPodani"],
                            favorite: true,
                        },
                        {
                            caption: "Podání ze šabl.",
                            tooltip: "Podání případu ze šablony",
                            icon: "gi-doc_vlastni_plus",
                            action: that.actions["actPodaniZeSablony"],
                            favorite: false,
                        },
                    ];
                    menu.push({
                        favorite: true,
                        type: "static",
                        caption: "Tisky",
                        icon: "gi-print",
                        children: that.createChildrenTisky()
                    });
                    menu.push({
                        favorite: true,
                        type: "static",
                        caption: "Hromadné změny",
                        children: that.createChildrenHromadneOperace()
                    });
                    menu.push({ action: that.actions.actVymahani, favorite: true });
                    menu.push({ action: that.actions.actVymahat, favorite: true });
                    menu.push({ action: that.actions.actPohledavkyPopl, favorite: true });
                    menu.push({
                        favorite: true,
                        type: "static",
                        caption: "Redistribuce",
                        children: that.createChildrenRedist()
                    });
                    // Pokud je správcovská typ pohledávky zobrazíme akce spojené se správou případu
                    if (that.PrizSpr == 1)
                        menu.push({ action: that.actions.actSpravaPripadu, favorite: true });
                    that.menuBar(menu);
                }
