                // #endregion
                // #region TISKY - akce
                //otevření okna pro detail tisku (zadání datového intervalu pro tisk a zobrazení popisu tisku)
                runTiskDetail(tema, nazev_funkce) {
                    const that = this;
                    var windowOption = { title: `Zadání parametrů tisku`, width: 475, height: 635 }; //nastavení okna
                    var ParamJSON = { ID: "DDPGTiskDetail#", tema: tema }; //přenášené parametry
                    this.dialogs.showModalWindow("Gordic.Ddp.WebClient.GTiskDetail", ParamJSON, windowOption)
                        .on("close", (ev, retVal) => {
                        //akce po uzavření okna
                        if (retVal != null) {
                            var filter = {};
                            filter.tema = tema;
                            filter.nazev_funkce = nazev_funkce;
                            filter.dat_od = retVal.dat_od;
                            filter.dat_do = retVal.dat_do;
                            if (retVal.select != null)
                                filter.select = retVal.select.id;
                            else
                                filter.select = null;
                            filter.napojene = retVal.napojene;
                            //call tisk
                            that.tiskBasic(filter);
                        }
                    });
                }
                runSIPODetail(tema, nazev_funkce) {
                    const that = this;
                    var windowOption = { title: `Zadání období pro SIPO`, width: 300, height: 270 }; //nastavení okna
                    var ParamJSON = { ID: "DDPGSIPODetail#", tema: tema }; //přenášené parametry
                    this.dialogs.showModalWindow("Gordic.Ddp.WebClient.GSIPODetail", ParamJSON, windowOption)
                        .on("close", (ev, retVal) => {
                        //akce po uzavření okna
                        if (retVal != null) {
                            var filter = {};
                            filter.tema = tema;
                            filter.nazev_funkce = nazev_funkce;
                            filter.rok = retVal.rok;
                            filter.mesic = retVal.mesic;
                            filter.select = retVal.select.id;
                            filter.napojene = retVal.napojene;
                            //call tisk
                            that.tiskBasic(filter);
                        }
                    });
                }
                runRozboruDetail(tema, nazev_funkce) {
                    const that = this;
                    var windowOption = { title: `Definice rozborů`, width: 350, height: 515 }; //nastavení okna
                    var ParamJSON = { ID: "DDPGRozboryDetail#", tema: tema }; //přenášené parametry
                    this.dialogs.showModalWindow("Gordic.Ddp.WebClient.GRozboryDetail", ParamJSON, windowOption)
                        .on("close", (ev, retVal) => {
                        //akce po uzavření okna
                        if (retVal != null) {
                            var filter = {};
                            filter.tema = tema;
                            filter.nazev_funkce = nazev_funkce;
                            filter.ned_od = retVal.ned_od;
                            filter.ned_do = retVal.ned_do;
                            filter.datum = retVal.datum;
                            var intervalVals = retVal.intervalVals;
                            //call tisk
                            that.tiskRozboru(filter, intervalVals);
                        }
                    });
                }
                //Základní obecný tisk, s hodnotami téma, datum od a datum do
                tiskBasic(filter_window) {
                    const that = this;
                    var ixps = [];
                    var rows;
                    //získání identifikátorů vybraných řádků
                    if (filter_window.select == 1) {
                        rows = that.gridSeznamPripadu.ggrid("getSelection");
                        for (var i = 0; i < rows.length; i++) {
                            ixps[i] = rows[i].ixp;
                        }
                    }
                    var filter = { typ_phl: that.filters.typ_phl };
                    if (filter_window.select == 2)
                        filter = that.filters;
                    const actTiskBasic = GAction.createPrintAction({
                        name: "actTiskBasic",
                        tema: filter_window.tema,
                        // ↓ Metoda, která je zavolána těsně před generováním sestavy a kde lze na straně serveru ovlivnit parametry sestavy ↓
                        serverParameterMethod: "Gordic.Ddp.WebClient.GDdpWebTisk:" + filter_window.nazev_funkce, //zde se plní téma
                        reportStarting: function (rep) {
                            rep.customDto = {
                                datumOd: filter_window.dat_od,
                                datumDo: filter_window.dat_do,
                                rok: filter_window.rok,
                                mesic: filter_window.mesic,
                                select: filter_window.select,
                                napojeno: filter_window.napojene,
                                basicTiskPodminkyFiltr: filter,
                                //basicTiskPodminkyFiltrTest: filter,
                                rows: ixps,
                                ixp_den: that.IxpDen,
                                rok_den: that.RokDen,
                                typ_phl: that.typ_phl
                            };
                        },
                        reportFinished: function () {
                            that.isl.TiskPodminky.delete().get(); //smazání dat z ddpttdp
                        },
                        dialogClosed: function () {
                            that.isl.TiskPodminky.delete().get();
                        }
                    });
                    actTiskBasic.run();
                }
                //Tisk rozboru samostatně, má jiné vstupní údaje než basic
                tiskRozboru(filter_window, intervalVals) {
                    var that = this;
                    var datumyIntervalu = [];
                    if (intervalVals.length != 0) {
                        for (var i = 0; i < intervalVals.length; i++) {
                            datumyIntervalu[i] = intervalVals[i].datum;
                        }
                    }
                    var filter = that.filters;
                    const actTiskSald = GAction.createPrintAction({
                        name: "actTiskBasic",
                        tema: filter_window.tema,
                        // ↓ Metoda, která je zavolána těsně před generováním sestavy a kde lze na straně serveru ovlivnit parametry sestavy ↓
                        serverParameterMethod: "Gordic.Ddp.WebClient.GDdpWebTisk:" + filter_window.nazev_funkce, //zde se plní téma
                        reportStarting: function (rep) {
                            rep.customDto = {
                                rozboryFiltr: filter_window,
                                basicTiskPodminkyFiltr: filter,
                                intervalVals: datumyIntervalu,
                                ixp_den: that.IxpDen,
                                rok_den: that.RokDen
                            };
                        },
                        reportFinished: function () {
                            that.isl.TiskPodminky.delete().get(); //smazání dat z ddpttdp
                        },
                        dialogClosed: function () {
                            that.isl.TiskPodminky.delete().get();
                        }
                    });
                    actTiskSald.run();
                }
                // #endregion
                naplneniPole(start, end) {
                    let a = [];
                    for (let i = 0; start < end; i++) {
                        a[i] = start;
                        start++;
                        //a.push([i]);
                    }
                    return a;
                }
                createPripad(l_ixpden) {
                    const that = this;
                    Gordic.Ddp.WebClient.Common.Pripady.sejmutiStitkem(that, that.GinGenIxp).then(function (ixpe) {
                        that.beginOperation("Probíhá zakládání nového případu...");
                        WebClient.Common.Base.ProcessResponse(that.isl.Pripad.create((rq) => {
                            return {
                                rq: {
                                    Data: {
                                        ixp_den: l_ixpden,
                                        ixp: ixpe,
                                        gin_gen_mode: that.GinGenIxp,
                                        zp: that.globalSettings?.get(`Global.Ddp.ObecneSettings.PredplneniZpUhr`) ?? 0
                                    },
                                },
                            };
                        }).get(), that, false, false)
                            .done((data) => {
                            //pokud je vše v pořádku, tak přejdu na detail případu
                            //? je tady nutný mít typ_phl na vstupu pro otevření detailu případu ?
                            WebClient.Common.Pripady.openPripadDetail(that, data.Dto.ixp);
                            //that.navigate(
                            //    "Gordic.Ddp.WebClient.GPripadDetail",
                            //    {
                            //        ID: "DDPGPripadDetail#",
                            //        Ixp: data.Dto!.ixp!,
                            //        TypPhl: data.Dto!.typ_phl!,
                            //    }
                            //);
                            that.endOperation();
                        })
                            //.fail(() => {
                            //    //todo:
                            //    that.endOperation();
                            //})
                            .fail(function (jqXHR, typ, obj) {
                            //něco se pokazilo
                            //vrátim hlášku o důvodu neúspěchu
                            that.endOperation();
                            //TEST:
                            if (typ === "exception") {
                                obj.handled = true;
                                return that.dialogs.error("Chyba", obj.baseMessage);
                            }
                        });
                    });
                }
