                //#region Hromadná aktualizace zákonných zástupců
                hromadnaOperaceZakZas(title, gridFormat, keys, form, lastStepTitle, massUpdate, checkFunction) {
                    var that = this;
                    this.navigate(Gordic.Eko.Components.TwoStepsContent, {
                        title: title,
                        gridFormat: gridFormat,
                        keys: keys,
                        data: that.gridSeznamPripadu.ggrid("getSelection"),
                        indicatorType: "KPI",
                        firstStep: {
                            form: form,
                            gridTabTitle: "Vybrané případy", //titulek v tabu   
                            defaultAction: that.actions["actGPripadySeznamGridVychoziAkce"],
                            showIndicator: true,
                            nextActionName: "Proveď", //název pro tlačítko další
                            nextAction: (_model, data) => {
                                var inputDate = $.content().findFields("inputDate").gfield("getValue");
                                var ixs_dva = $.content().findFields("ixs_dva").gfield("getValue");
                                var hledat_odstehovane = $.content().findFields("hledat_odstehovane").gfield("getValue");
                                var pridat_vsechny = $.content().findFields("pridat_vsechny").gfield("getValue");
                                var pridat_odkaz_na_sebe = $.content().findFields("pridat_odkaz_na_sebe").gfield("getValue");
                                var odstranit_stare = $.content().findFields("odstranit_stare").gfield("getValue");
                                //uložení hodnot do usersettings
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.dat_nar_od", inputDate);
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.hledat_odstehovane", hledat_odstehovane);
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.pridat_vsechny", pridat_vsechny);
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.pridat_odkaz_na_sebe", pridat_odkaz_na_sebe);
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.odstranit_stare", odstranit_stare);
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.ixs_dva", ixs_dva);
                                //nalezení tabulky
                                var grid = $('.gform-field[data-help-context="list:gridTypyVztahu"]');
                                var gridView = grid.ggrid("getView");
                                var rows = gridView.getDataRows(true);
                                var typVztahu = "";
                                rows.forEach((row) => {
                                    if (row.checked) {
                                        typVztahu += row.data.typ_vztahu + ",";
                                    }
                                });
                                if (typVztahu != "") {
                                    typVztahu = typVztahu.replace(/,$/, "");
                                }
                                that.globalSettings.set("Global.Ddp.AktualizaceZakZas.typ_vztahu", typVztahu);
                                if (ixs_dva != undefined)
                                    ixs_dva = ixs_dva.ixs_dva;
                                const modelDto = {
                                    inputDate: inputDate,
                                    inputString: typVztahu,
                                    ixs_dva: ixs_dva,
                                    hledat_odstehovane: hledat_odstehovane,
                                    pridat_vsechny: pridat_vsechny,
                                    pridat_odkaz_na_sebe: pridat_odkaz_na_sebe,
                                    odstranit_stare: odstranit_stare
                                };
                                return massUpdate({ dtos: data, model: modelDto }).get()
                                    .then((result) => {
                                    return Gordic.Eko.Components.Wizard.Utils.getData(result);
                                });
                            },
                            checkAction: (model, data) => {
                                const modelDto = {
                                    reason: model.reason
                                };
                                return checkFunction({ dtos: data, model: modelDto }).get()
                                    .then((result) => {
                                    return Gordic.Eko.Components.Wizard.Utils.getData(result);
                                });
                            }
                        },
                        lastStep: {
                            // fáze 2 - zobrazení­ výsledku storna
                            title: lastStepTitle, //nazev kroku
                            defaultAction: that.actions["actGPripadySeznamGridVychoziAkce"],
                            gridTabTitle: "Aktualizované pří­pady", //popisek nad gridem
                            form: form,
                            modelData: () => {
                                return {
                                    reason: ""
                                };
                            }
                        },
                        completeDelegate: () => {
                            //that.ziskejData(that.filterData);
                            if (that.view)
                                that.view.requestData();
                        },
                        cancelDelegate: () => {
                        }
                    }).createDialogPromise();
                }
